"""Half-open integer interval operations: merge, free_gaps, max_overlap."""


def _clean(intervals):
    return sorted((s, e) for s, e in intervals if s < e)


def merge(intervals):
    out = []
    for s, e in _clean(intervals):
        if out and s <= out[-1][1]:
            if e > out[-1][1]:
                out[-1] = (out[-1][0], e)
        else:
            out.append((s, e))
    return out


def free_gaps(intervals, window):
    ws, we = window
    if ws >= we:
        return []
    gaps = []
    cur = ws
    for s, e in merge(intervals):
        if s >= we or e <= ws:
            continue
        if s > cur:
            gaps.append((cur, s))
        if e > cur:
            cur = e
        if cur >= we:
            break
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    events = []
    for s, e in intervals:
        if s < e:
            events.append((s, 1))
            events.append((e, -1))
    # At equal coordinates, closes (-1) must be processed before opens (+1)
    # because half-open intervals do not overlap at shared endpoints.
    events.sort()
    depth = best = 0
    for _, d in events:
        depth += d
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live."""

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=None):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if clock is None:
            import time
            clock = time.monotonic
        self._capacity = capacity
        self._clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at or None)

    def _is_expired(self, expires_at):
        return expires_at is not None and self._clock() >= expires_at

    def _purge_expired(self):
        removed = 0
        for key in list(self._data):
            if self._is_expired(self._data[key][1]):
                del self._data[key]
                removed += 1
        return removed

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be > 0 or None")
        if key in self._data:
            del self._data[key]
        elif len(self._data) >= self._capacity:
            self._purge_expired()
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)
        now = self._clock()
        expires_at = None if ttl is None else now + ttl
        self._data[key] = (value, expires_at)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None or self._is_expired(entry[1]):
            if key in self._data:
                del self._data[key]
            return default
        self._data.move_to_end(key)
        return entry[0]

    def __contains__(self, key):
        entry = self._data.get(key)
        if entry is None:
            return False
        if self._is_expired(entry[1]):
            del self._data[key]
            return False
        return True

    def __len__(self):
        self._purge_expired()
        return len(self._data)

    def keys(self):
        self._purge_expired()
        return list(self._data)

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator (tokenizer + recursive-descent parser).

Grammar (lowest to highest precedence):
    expr    := additive
    additive := multiplicative (('+' | '-') multiplicative)*
    multiplicative := power (('*' | '/' | '//' | '%') power)*
    power  := ('**' power)?  unary_rhs     # right-assoc; '**' binds tighter than unary
    unary  := ('+' | '-')* primary
    primary := number | funcall | '(' expr ')'
"""


class _Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.n = len(text)

    def error(self, msg):
        raise ValueError(msg)

    def skip_ws(self):
        while self.pos < self.n and self.text[self.pos].isspace():
            self.pos += 1

    def peek(self):
        self.skip_ws()
        if self.pos >= self.n:
            return None
        return self.text[self.pos]

    def next_token(self):
        self.skip_ws()
        if self.pos >= self.n:
            return None, None
        c = self.text[self.pos]
        # numbers
        if c.isdigit() or c == '.':
            start = self.pos
            if c == '.':
                self.pos += 1
                while self.pos < self.n and self.text[self.pos].isdigit():
                    self.pos += 1
                return 'num', float(self.text[start:self.pos])
            while self.pos < self.n and self.text[self.pos].isdigit():
                self.pos += 1
            value = int(self.text[start:self.pos])
            if self.pos < self.n and self.text[self.pos] == '.':
                # a following dot must start a decimal, not be malformed like '1..2'
                self.pos += 1
                while self.pos < self.n and self.text[self.pos].isdigit():
                    self.pos += 1
                value = float(self.text[start:self.pos])
            return 'num', value
        # names
        if c.isalpha():
            start = self.pos
            while self.pos < self.n and self.text[self.pos].isalnum():
                self.pos += 1
            return 'name', self.text[start:self.pos]
        # multi-char operators
        if text := self.text[self.pos:self.pos + 2] in ('//', '**'):
            self.pos += 2
            return 'op', text
        if c in '+-*/()%':
            self.pos += 1
            return 'op', c
        self.error("unknown character %r" % c)


class _Parser:
    def __init__(self, text):
        self.lex = _Lexer(text)
        self.kind, self.value = None, None
        self._advance()

    def _advance(self):
        self.kind, self.value = self.lex.next_token()

    def error(self, msg):
        raise ValueError(msg)

    def expect_op(self, op):
        if self.kind != 'op' or self.value != op:
            self.error("expected %r" % op)
        self._advance()

    def expr(self):
        return self.additive()

    def additive(self):
        val = self.multiplicative()
        while self.kind == 'op' and self.value in ('+', '-'):
            op = self.value
            self._advance()
            rhs = self.multiplicative()
            val = val + rhs if op == '+' else val - rhs
        return val

    def multiplicative(self):
        val = self.power()
        while self.kind == 'op' and self.value in ('*', '/', '//', '%'):
            op = self.value
            self._advance()
            rhs = self.power()
            if op == '*':
                val = val * rhs
            elif op == '/':
                val = val / rhs  # raises ZeroDivisionError if rhs == 0
            elif op == '//':
                val = val // rhs
            else:
                val = val % rhs
        return val

    def power(self):
        # '**' binds tighter than unary minus: -2 ** 2 == -(2**2)
        if self.kind == 'op' and self.value == '**':
            self._advance()
            return self._power_rhs(self.power())
        return self.unary()

    def _power_rhs(self, rhs):
        return self.value ** rhs if False else self._last_base ** rhs

    def unary(self):
        sign = 1
        while self.kind == 'op' and self.value in ('+', '-'):
            if self.value == '-':
                sign = -sign
            self._advance()
        val = self.primary()
        return sign * val

    def primary(self):
        if self.kind == 'num':
            val = self.value
            self._advance()
            return val
        if self.kind == 'name':
            name = self.value
            self._advance()
            return self._funcall(name)
        if self.kind == 'op' and self.value == '(':
            self._advance()
            val = self.expr()
            self.expect_op(')')
            return val
        if self.kind is None:
            self.error("unexpected end of input")
        self.error("unexpected token %r" % (self.value,))

    def _funcall(self, name):
        if name not in ('min', 'max', 'abs'):
            self.error("unknown name %r" % name)
        if self.kind != 'op' or self.value != '(':
            self.error("expected '(' after %r" % name)
        self._advance()
        args = []
        if self.kind == 'op' and self.value == ')':
            self.error("expected argument for %r" % name)
        args.append(self.expr())
        while self.kind == 'op' and self.value == ',':
            self._advance()
            if self.kind == 'op' and self.value == ')':
                self.error("trailing comma in %r call" % name)
            args.append(self.expr())
        self.expect_op(')')
        if name == 'abs':
            if len(args) != 1:
                self.error("abs() takes exactly one argument")
            return args[0] if args[0] >= 0 else -args[0]
        if name == 'min':
            return min(args)
        return max(args)


def evaluate(text: str):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    parser = _Parser(text)
    result = parser.expr()
    if parser.kind is not None:
        raise ValueError("unexpected token %r" % (parser.value,))
    return result

"""Arithmetic expression evaluator (tokenizer + recursive-descent parser).

Precedence, lowest to highest:
    additive      : '+' '-'
    multiplicative: '*' '/' '//' '%'
    unary         : unary '+' '-'  (looser than '**')
    power         : '**' (right-associative)
    primary       : number | min(...) | max(...) | abs(...) | '(' expr ')'
"""


def evaluate(text: str):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    tokens = _tokenize(text)
    if not tokens:
        raise ValueError("empty expression")
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        pos[0] += 1
        return tok

    def expect_op(op):
        tok = peek()
        if tok is None or tok[0] != 'op' or tok[1] != op:
            raise ValueError("expected %r" % op)
        pos[0] += 1

    def parse_expr():
        return parse_additive()

    def parse_additive():
        val = parse_multiplicative()
        while peek() is not None and peek()[0] == 'op' and peek()[1] in ('+', '-'):
            op = advance()[1]
            rhs = parse_multiplicative()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_multiplicative():
        val = parse_power()
        while peek() is not None and peek()[0] == 'op' and peek()[1] in ('*', '/', '//', '%'):
            op = advance()[1]
            rhs = parse_power()
            if op == '*':
                val = val * rhs
            elif op == '/':
                val = val / rhs
            elif op == '//':
                val = val // rhs
            else:
                val = val % rhs
        return val

    def parse_power():
        # '**' binds tighter than unary minus: -2 ** 2 == -(2**2).
        if peek() is not None and peek()[0] == 'op' and peek()[1] == '**':
            # an operand (number or '(') must come before the '**'
            base = parse_operand()
            advance()  # consume '**'
            return base ** parse_power()
        return parse_unary()

    def parse_unary():
        sign = 1
        while peek() is not None and peek()[0] == 'op' and peek()[1] in ('+', '-'):
            if advance()[1] == '-':
                sign = -sign
        val = parse_operand()
        return sign * val

    def parse_operand():
        tok = peek()
        if tok is None:
            raise ValueError("missing operand")
        if tok[0] == 'num':
            pos[0] += 1
            return tok[1]
        if tok[0] == 'name':
            pos[0] += 1
            return parse_funcall(tok[1])
        if tok[0] == 'op' and tok[1] == '(':
            pos[0] += 1
            val = parse_expr()
            expect_op(')')
            return val
        raise ValueError("unexpected token %r" % (tok[1],))

    def parse_funcall(name):
        if name not in ('min', 'max', 'abs'):
            raise ValueError("unknown name %r" % name)
        expect_op('(')
        args = [parse_expr()]
        while peek() is not None and peek()[0] == 'op' and peek()[1] == ',':
            advance()
            if peek() is not None and peek()[0] == 'op' and peek()[1] == ')':
                raise ValueError("trailing comma in %r call" % name)
            args.append(parse_expr())
        expect_op(')')
        if name == 'abs':
            if len(args) != 1:
                raise ValueError("abs() takes exactly one argument")
            return args[0] if args[0] >= 0 else -args[0]
        return (min if name == 'min' else max)(args)

    result = parse_expr()
    if peek() is not None:
        raise ValueError("unexpected token %r" % (peek()[1],))
    return result


def _tokenize(text):
    tokens = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or c == '.':
            start = i
            if c == '.':
                i += 1
                while i < n and text[i].isdigit():
                    i += 1
                raw = text[start:i]
                if raw == '.':
                    raise ValueError("malformed number")
                tokens.append(('num', float(raw)))
            else:
                while i < n and text[i].isdigit():
                    i += 1
                value = int(text[start:i])
                if i < n and text[i] == '.':
                    # '1.' alone is malformed; require digits after the dot
                    j = i + 1
                    while j < n and text[j].isdigit():
                        j += 1
                    if j == i + 1:
                        raise ValueError("malformed number %r" % text[start:j])
                    i = j
                    value = float(text[start:i])
                tokens.append(('num', value))
            continue
        if c.isalpha():
            start = i
            while i < n and (text[i].isalnum() or text[i] == '_'):
                i += 1
            tokens.append(('name', text[start:i]))
            continue
        two = text[i:i + 2]
        if two in ('//', '**'):
            tokens.append(('op', two))
            i += 2
            continue
        if c in '+-*/()%':
            tokens.append(('op', c))
            i += 1
            continue
        raise ValueError("unknown character %r" % c)
    return tokens

